const lead = $json;

const errors = [];

if (!lead.name || String(lead.name).trim() === "") {
  errors.push("name is required");
}

if (!lead.email || String(lead.email).trim() === "") {
  errors.push("email is required");
}

if (!lead.business || String(lead.business).trim() === "") {
  errors.push("business is required");
}

if (!lead.service || String(lead.service).trim() === "") {
  errors.push("service is required");
}

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (lead.email && !emailRegex.test(String(lead.email).trim())) {
  errors.push("invalid email format");
}

const phone = String(lead.phone || "").replace(/\D/g, "");

if (phone.length < 10 || phone.length > 15) {
  errors.push("invalid phone number");
}

const budget = Number(lead.budget);

if (!Number.isFinite(budget) || budget < 0) {
  errors.push("invalid budget");
}

return [
  {
    json: {
      ...lead,
      is_valid: errors.length === 0,
      validation_errors: errors,
      status: errors.length === 0 ? "NEW" : "INVALID"
    }
  }
];

const lead = $json;

let score = 0;
const scoring_reasons = [];

// =========================
// BUDGET SCORE
// =========================

const budget = Number(lead.budget);

if (budget >= 10000000) {
  score += 40;
  scoring_reasons.push("High budget");
} else if (budget >= 5000000) {
  score += 30;
  scoring_reasons.push("Medium-high budget");
} else if (budget >= 2000000) {
  score += 20;
  scoring_reasons.push("Medium budget");
} else if (budget >= 1000000) {
  score += 10;
  scoring_reasons.push("Low-medium budget");
}

// =========================
// SERVICE SCORE
// =========================

const service = String(lead.service || "").toLowerCase();

const highValueServices = [
  "website",
  "web development",
  "web app",
  "application",
  "mobile app",
  "ecommerce"
];

if (highValueServices.some(item => service.includes(item))) {
  score += 20;
  scoring_reasons.push("High-value service");
} else if (service) {
  score += 10;
  scoring_reasons.push("Service provided");
}

// =========================
// BUSINESS INFORMATION
// =========================

if (lead.business && String(lead.business).trim().length >= 3) {
  score += 15;
  scoring_reasons.push("Business information provided");
}

// =========================
// CONTACT INFORMATION
// =========================

if (lead.email) {
  score += 10;
  scoring_reasons.push("Email provided");
}

if (lead.phone) {
  score += 5;
  scoring_reasons.push("Phone provided");
}

// =========================
// LEAD CLASSIFICATION
// =========================

let priority;

if (score >= 70) {
  priority = "HIGH";
} else if (score >= 40) {
  priority = "MEDIUM";
} else {
  priority = "LOW";
}

return [
  {
    json: {
      ...lead,
      score,
      priority,
      scoring_reasons
    }
  }
];

