const currentLead = $('Lead Scoring').item.json;

const currentEmail = String(currentLead.email || "")
  .trim()
  .toLowerCase();

const currentPhoneDigits = String(currentLead.phone || "")
  .replace(/\D/g, "");

const existingRows = $input.all()
  .map(i => i.json)
  .filter(row =>
    row.email ||
    row.phone ||
    row.lead_id
  );

const match = existingRows.find(row => {
  const rowEmail = String(row.email || "")
    .trim()
    .toLowerCase();

  if (
    rowEmail &&
    currentEmail &&
    rowEmail === currentEmail
  ) {
    return true;
  }

  const rowPhoneDigits = String(row.phone || "")
    .replace(/\D/g, "");

  if (
    currentPhoneDigits &&
    rowPhoneDigits &&
    rowPhoneDigits === currentPhoneDigits
  ) {
    return true;
  }

  return false;
});

return [
  {
    json: {
      ...currentLead,
      is_duplicate: Boolean(match),
      duplicate_matched_lead_id: match
        ? (match.lead_id || null)
        : null,
      duplicate_matched_email: match
        ? match.email
        : null
    }
  }
];

